export const TIMING = {"duration": 60.957031, "total_frames": 1829, "phrases": [{"n": 1, "text": "Everyone on the hill laughed at Dev. He had tied a bottle to his kite.", "s": 0.019, "e": 2.892, "f0": 1, "f1": 87}, {"n": 2, "text": "Not for luck. He wanted to hear the wind sing.", "s": 3.35, "e": 5.453, "f0": 100, "f1": 164}, {"n": 3, "text": "Tomorrow was the great kite contest, and the high wind would pick the winner.", "s": 5.898, "e": 9.243, "f0": 177, "f1": 277}, {"n": 4, "text": "Kabir laughed loudest: \"A bottle? Tie a drum too. Make a band!\"", "s": 9.544, "e": 13.09, "f0": 286, "f1": 393}, {"n": 5, "text": "Dev only smiled, and let his kite climb.", "s": 13.637, "e": 15.88, "f0": 409, "f1": 476}, {"n": 6, "text": "Then, faint as a mosquito, the bottle began to hum.", "s": 16.038, "e": 18.81, "f0": 481, "f1": 564}, {"n": 7, "text": "Kabir cupped his ear. \"That's no song. That's a bee with a cold.\"", "s": 19.095, "e": 22.48, "f0": 573, "f1": 674}, {"n": 8, "text": "Dev said, \"Just listen. The note is climbing.\"", "s": 22.78, "e": 25.18, "f0": 683, "f1": 755}, {"n": 9, "text": "And it was. The higher the kite rose, the louder the bottle sang.", "s": 25.757, "e": 28.932, "f0": 773, "f1": 868}, {"n": 10, "text": "But over Kabir's side of the hill, the hum sank\u2026 and died.", "s": 29.043, "e": 32.293, "f0": 871, "f1": 969}, {"n": 11, "text": "You see, everyone has blown across a bottle at home.", "s": 33.043, "e": 35.598, "f0": 991, "f1": 1068}, {"n": 12, "text": "A soft blow sings low. A hard blow sings high.", "s": 36.32, "e": 38.952, "f0": 1090, "f1": 1169}, {"n": 13, "text": "That bottle was an ear in the sky. It heard wind nobody could feel below.", "s": 39.4, "e": 42.522, "f0": 1182, "f1": 1276}, {"n": 14, "text": "All week, Kabir had sworn his side had the finest wind on the hill.", "s": 42.99, "e": 46.218, "f0": 1290, "f1": 1387}, {"n": 15, "text": "The bottle told the whole hill the truth. His side had none.", "s": 46.637, "e": 49.885, "f0": 1399, "f1": 1497}, {"n": 16, "text": "Next morning, Dev flew where the note sang highest. His kite won by a mile.", "s": 49.922, "e": 53.642, "f0": 1498, "f1": 1609}, {"n": 17, "text": "Kabir's kite sank out of the dead air\u2026 straight into the pond, in front of everyone.", "s": 53.928, "e": 57.823, "f0": 1618, "f1": 1735}, {"n": 18, "text": "But tomorrow\u2026 the boy who tied a bell to a cloud?", "s": 58.233, "e": 60.63, "f0": 1747, "f1": 1819}]};
